import "core-js/modules/es.array.push.js";
import AppLayout from "@/components/AppLayout.vue";
import request from "@/utils/axios"; // 导入配置好的axios实例
import eventBus from "@/utils/eventBus"; // 导入事件总线
import { User, Medal, OfficeBuilding, Phone, Message } from "@element-plus/icons-vue";
export default {
  name: "ProfileView",
  components: {
    AppLayout,
    User,
    Medal,
    OfficeBuilding,
    Phone,
    Message
  },
  data() {
    // 确认密码的验证规则
    const validateConfirmPassword = (rule, value, callback) => {
      if (value !== this.passwordForm.newPassword) {
        callback(new Error("两次输入的密码不一致"));
      } else {
        callback();
      }
    };
    return {
      activeTab: "info",
      userInfo: {
        doctorId: 0,
        username: "",
        realName: "",
        title: "",
        department: "",
        phone: "",
        email: "",
        avatar: "https://cube.elemecdn.com/0/88/03b0d39583f48206768a7534e55bcpng.png"
      },
      rules: {
        realName: [{
          required: true,
          message: "请输入真实姓名",
          trigger: "blur"
        }, {
          min: 2,
          max: 20,
          message: "长度在 2 到 20 个字符",
          trigger: "blur"
        }],
        title: [{
          required: true,
          message: "请选择职称",
          trigger: "change"
        }],
        department: [{
          required: true,
          message: "请输入科室",
          trigger: "blur"
        }],
        phone: [{
          required: true,
          message: "请输入手机号码",
          trigger: "blur"
        }, {
          pattern: /^1[3-9]\d{9}$/,
          message: "请输入正确的手机号码",
          trigger: "blur"
        }],
        email: [{
          required: true,
          message: "请输入邮箱",
          trigger: "blur"
        }, {
          type: "email",
          message: "请输入正确的邮箱地址",
          trigger: "blur"
        }]
      },
      passwordForm: {
        currentPassword: "",
        newPassword: "",
        confirmPassword: ""
      },
      passwordRules: {
        currentPassword: [{
          required: true,
          message: "请输入当前密码",
          trigger: "blur"
        }],
        newPassword: [{
          required: true,
          message: "请输入新密码",
          trigger: "blur"
        }, {
          min: 6,
          message: "密码长度不能小于6个字符",
          trigger: "blur"
        }],
        confirmPassword: [{
          required: true,
          message: "请再次输入新密码",
          trigger: "blur"
        }, {
          validator: validateConfirmPassword,
          trigger: "blur"
        }]
      },
      settingsForm: {
        systemNotification: true,
        diagnosisNotification: true,
        anomalyNotification: true,
        language: "zh-CN",
        themeColor: "#fff",
        tablePageSize: 20
      },
      feedbackForm: {
        type: "",
        content: "",
        contact: ""
      },
      feedbackRules: {
        type: [{
          required: true,
          message: "请选择反馈类型",
          trigger: "change"
        }],
        content: [{
          required: true,
          message: "请输入反馈内容",
          trigger: "blur"
        }, {
          min: 10,
          message: "反馈内容不能少于10个字符",
          trigger: "blur"
        }]
      },
      passwordLoading: false
    };
  },
  methods: {
    // 触发文件选择器
    triggerAvatarUpload() {
      this.$refs.avatarUpload.click();
    },
    // 处理头像变更
    handleAvatarChange(e) {
      const file = e.target.files[0];
      if (!file) return;

      // 检查文件类型
      if (!file.type.includes("image")) {
        this.$message.error("请上传图片文件");
        return;
      }

      // 检查文件大小 (限制为2MB)
      if (file.size > 2 * 1024 * 1024) {
        this.$message.error("图片大小不能超过2MB");
        return;
      }
      this.uploadAvatar(file);
    },
    // 上传头像到服务器
    uploadAvatar(file) {
      this.avatarLoading = true;

      // 创建FormData对象
      const formData = new FormData();
      formData.append("file", file);

      // 上传文件
      request({
        url: "/common/upload",
        method: "post",
        data: formData,
        headers: {
          "Content-Type": "multipart/form-data"
        }
      }).then(response => {
        if (response.code === 200 || response.code === 1) {
          // 获取文件路径
          const filepath = response.data;
          // 更新医生头像
          this.updateDoctorAvatar(filepath);
        } else {
          this.$message.error(response.msg || "文件上传失败");
          this.avatarLoading = false;
        }
      }).catch(error => {
        console.error("文件上传失败:", error);
        this.$message.error("文件上传失败，请稍后重试");
        this.avatarLoading = false;
      });
    },
    // 更新医生头像信息
    updateDoctorAvatar(filepath) {
      // 获取当前医生ID
      const userInfo = JSON.parse(localStorage.getItem("userInfo") || "{}");
      const doctorId = userInfo.doctorId || userInfo.id;

      // 构造请求数据
      const data = {
        id: doctorId,
        filepath: filepath
      };

      // 发送更新请求
      request({
        url: "/doctor/update/image",
        method: "put",
        data: data
      }).then(response => {
        if (response.code === 200 || response.code === 1) {
          // 更新本地头像
          this.userInfo.avatar = filepath;

          // 更新本地存储
          const storedUserInfo = JSON.parse(localStorage.getItem("userInfo") || "{}");
          storedUserInfo.avatar = filepath;
          storedUserInfo.image = filepath; // 确保两个字段都更新
          localStorage.setItem("userInfo", JSON.stringify(storedUserInfo));

          // 通知其他组件用户信息已更新
          eventBus.emit("userInfoUpdated", storedUserInfo);
          this.$message.success("头像更新成功");
        } else {
          this.$message.error(response.msg || "头像更新失败");
        }
      }).catch(error => {
        console.error("头像更新失败:", error);
        this.$message.error("头像更新失败，请稍后重试");
      }).finally(() => {
        this.avatarLoading = false;
      });
    },
    saveUserInfo() {
      this.$refs.userForm.validate(valid => {
        if (valid) {
          // 构造要提交的数据
          const userData = {
            doctorId: this.userInfo.doctorId,
            name: this.userInfo.realName,
            username: this.userInfo.username,
            phoneNumber: this.userInfo.phone,
            department: this.userInfo.department,
            doctorTitle: this.userInfo.title,
            email: this.userInfo.email
          };

          // 发送更新请求
          request({
            url: "/doctor/update",
            method: "put",
            data: userData
          }).then(response => {
            if (response.code === 200 || response.code === 1) {
              this.$message.success("个人信息更新成功");
              // 更新本地存储的用户信息
              const userInfo = JSON.parse(localStorage.getItem("userInfo") || "{}");
              localStorage.setItem("userInfo", JSON.stringify({
                ...userInfo,
                ...userData
              }));
              // 通知其他组件用户信息已更新
              eventBus.emit("userInfoUpdated", {
                ...userInfo,
                ...userData
              });
            } else {
              this.$message.error(response.msg || "更新失败");
            }
          }).catch(error => {
            console.error("更新个人信息失败:", error);
            this.$message.error("更新失败，请稍后重试");
          });
        } else {
          return false;
        }
      });
    },
    resetForm(formName) {
      this.$refs[formName].resetFields();
    },
    changePassword() {
      this.$refs.passwordForm.validate(valid => {
        if (valid) {
          // 获取当前医生ID
          const userInfo = JSON.parse(localStorage.getItem("userInfo") || "{}");
          const doctorId = userInfo.doctorId || userInfo.id;

          // 构造请求数据
          const passwordData = {
            doctorId: doctorId,
            oldPassword: this.passwordForm.currentPassword,
            newPassword: this.passwordForm.newPassword
          };

          // 设置加载状态
          this.passwordLoading = true;

          // 发送更新请求
          request({
            url: "/doctor/update/password",
            method: "put",
            data: passwordData
          }).then(response => {
            if (response.code === 200 || response.code === 1) {
              this.$message.success("密码修改成功，请重新登录");
              setTimeout(() => {
                localStorage.removeItem("token");
                localStorage.removeItem("isLoggedIn");
                this.$router.push("/login");
              }, 1500);
            } else {
              this.$message.error(response.msg || "密码修改失败");
            }
          }).catch(error => {
            console.error("修改密码失败:", error);
            this.$message.error("修改密码失败，请稍后重试");
          }).finally(() => {
            this.passwordLoading = false;
          });
        } else {
          return false;
        }
      });
    },
    saveSettings() {
      this.$message.success("系统设置保存成功");
      // 实际应用中这里应该将设置保存到本地存储或后端
    },
    resetSettings() {
      this.settingsForm = {
        systemNotification: true,
        diagnosisNotification: true,
        anomalyNotification: true,
        language: "zh-CN",
        themeColor: "#409EFF",
        tablePageSize: 20
      };
      this.$message.info("已恢复默认设置");
    },
    submitFeedback() {
      this.$refs.feedbackForm.validate(valid => {
        if (valid) {
          this.$message.success("感谢您的反馈，我们会尽快处理");
          this.resetForm("feedbackForm");
        } else {
          return false;
        }
      });
    },
    fetchDoctorInfo() {
      const token = localStorage.getItem("token");
      if (!token) return;

      // 获取当前登录的医生ID
      const userInfo = JSON.parse(localStorage.getItem("userInfo") || "{}");
      const doctorId = userInfo.id || localStorage.getItem("doctorId");
      if (doctorId) {
        // 根据ID查询医生信息
        request({
          url: `/doctor/${doctorId}`,
          method: "get"
        }).then(response => {
          if (response.code === 200 || response.code === 1) {
            const data = response.data;
            // Update userInfo with data from backend
            if (data) {
              this.userInfo = {
                doctorId: data.doctorId || data.id,
                username: data.username || this.userInfo.username,
                realName: data.name || this.userInfo.realName,
                title: data.doctorTitle || this.userInfo.title,
                department: data.department || this.userInfo.department,
                phone: data.phoneNumber || this.userInfo.phone,
                email: data.email || this.userInfo.email,
                avatar: data.image || data.avatar || this.userInfo.avatar // 优先使用后端返回的头像
              };

              // 更新本地存储
              localStorage.setItem("userInfo", JSON.stringify({
                ...data,
                avatar: data.image || data.avatar || this.userInfo.avatar // 确保头像字段被正确保存
              }));

              // 通知其他组件用户信息已更新
              eventBus.emit("userInfoUpdated", {
                ...data,
                avatar: data.image || data.avatar || this.userInfo.avatar
              });
            }
          } else {
            this.$message.error(response.msg || "获取用户信息失败");
          }
        }).catch(error => {
          console.error("获取用户信息失败:", error);
          this.$message.error("获取用户信息失败，请刷新重试");
        });
      } else {
        // 如果没有ID，则使用通用接口获取当前登录医生信息
        request({
          url: "/doctor/info",
          method: "get"
        }).then(response => {
          if (response.code === 200 || response.code === 1) {
            const data = response.data;
            // Update userInfo with data from backend
            if (data) {
              this.userInfo = {
                doctorId: data.doctorId || 0,
                username: data.username || this.userInfo.username,
                realName: data.name || this.userInfo.realName,
                title: data.doctorTitle || this.userInfo.title,
                department: data.department || this.userInfo.department,
                phone: data.phoneNumber || this.userInfo.phone,
                email: data.email || this.userInfo.email,
                avatar: data.image || data.avatar || this.userInfo.avatar // 优先使用后端返回的头像
              };

              // 更新本地存储
              localStorage.setItem("userInfo", JSON.stringify({
                ...data,
                avatar: data.image || data.avatar || this.userInfo.avatar // 确保头像字段被正确保存
              }));

              // 通知其他组件用户信息已更新
              eventBus.emit("userInfoUpdated", {
                ...data,
                avatar: data.image || data.avatar || this.userInfo.avatar
              });
            }
          } else {
            this.$message.error(response.msg || "获取用户信息失败");
          }
        }).catch(error => {
          console.error("获取用户信息失败:", error);
          this.$message.error("获取用户信息失败，请刷新重试");
        });
      }
    }
  },
  mounted() {
    // 检查登录状态
    const isLoggedIn = localStorage.getItem("token");
    if (!isLoggedIn) {
      this.$router.push("/login");
      return;
    }

    // 从localStorage加载用户信息
    const storedUserInfo = localStorage.getItem("userInfo");
    if (storedUserInfo) {
      try {
        const parsedInfo = JSON.parse(storedUserInfo);
        this.userInfo = {
          doctorId: parsedInfo.doctorId || 0,
          username: parsedInfo.username || "",
          realName: parsedInfo.name || "",
          title: parsedInfo.doctorTitle || "",
          department: parsedInfo.department || "",
          phone: parsedInfo.phoneNumber || "",
          email: parsedInfo.email || "",
          avatar: parsedInfo.avatar || "https://cube.elemecdn.com/0/88/03b0d39583f48206768a7534e55bcpng.png"
        };
      } catch (e) {
        console.error("Failed to parse user info:", e);
      }
    }

    // 获取最新的医生信息
    this.fetchDoctorInfo();
  }
};
